export const CAPODANNO_EVENTS: readonly CapodannoEventItem[] = [...UNSORTED_CAPODANNO_EVENTS].sort(
  (a, b) => getCapodannoPriorityRank(a.slug) - getCapodannoPriorityRank(b.slug)
);

export function getCapodannoEventBySlug(slug: string): CapodannoEventItem | undefined {
  return CAPODANNO_EVENTS.find((item) => item.slug === slug);
}

export function getCapodannoEventsByCategory(category?: CapodannoCategory): readonly CapodannoEventItem[] {
  const openEvents = CAPODANNO_EVENTS.filter((item) => !item.closedForNye && !item.soldOutForNye);
  if (!category) return openEvents;
  return openEvents.filter((item) => item.category === category);
}

export function getCapodannoEventsForMode(mode: string): readonly CapodannoEventItem[] {
  const openEvents = CAPODANNO_EVENTS.filter((item) => !item.closedForNye && !item.soldOutForNye);
  let list: readonly CapodannoEventItem[];
  if (mode === 'master' || mode === 'capodanno-2027') {
    list = openEvents;
  } else if (mode === 'milano-club' || mode === 'capodanno-speciale' || mode === 'lombardia' || mode === 'piazza') {
    list = openEvents.filter((item) => item.category === mode);
  } else {
    list = openEvents.filter((item) => item.subCategories.includes(mode as CapodannoSubCategorySlug));
  }
  return [...list].sort((a, b) => getCapodannoPriorityRank(a.slug, mode) - getCapodannoPriorityRank(b.slug, mode));
}

export function getCapodannoCategoryPageDef(slugOrMode: string): CapodannoCategoryPageDef {
  const normalized =
    slugOrMode === 'master'
      ? 'capodanno-2027'
      : slugOrMode === 'lombardia'
        ? 'capodanno-lombardia'
        : slugOrMode === 'piazza'
          ? 'capodanno-in-piazza'
          : slugOrMode;
  return CAPODANNO_CATEGORY_PAGES.find((p) => p.slug === normalized) || CAPODANNO_CATEGORY_PAGES[0];
}

